In OfflineQueue add a re-entrancy guard so overlapping calls coalesce, and verify the head before mutating:

```swift
private var inFlight: Task<FlushResult, Never>?

public func flush(using executor: any QueuedOperationExecutor) async -> FlushResult {
    if let inFlight { return await inFlight.value }
    let task = Task { await self.run(executor) }
    inFlight = task
    defer { inFlight = nil }
    return await task.value
}

private func run(_ executor: any QueuedOperationExecutor) async -> FlushResult {
    var result = FlushResult()
    while let item = items.first {
        do {
            try await executor.execute(item)
            result.sent += 1
        } catch let error as BackendError where !Self.isTransient(error) {
            result.rejected.append(item)
        } catch {
            if items.first?.id == item.id { items[0].attempts += 1 }
            break
        }
        if items.first?.id == item.id { items.removeFirst() }
        persist()
    }
    persist()
    result.remaining = items.count
    return result
}
```

